      setUp(() {
        io = FakeCliIO();
        shell = _SealShell();
        stream = _SealStream(List.of(_leadScripts));
        env = MemoryExecutionEnv(cwd: '/work', shell: shell);
        cli = _cli(
          io: io,
          env: env,
          stream: stream,
          drainMs: drainMs,
