      );
      expect(warnings, hasLength(2));
      expect(warnings.last, contains('obligations_ledger'));

      final customs = [
        for (final record in await recordsOnDisk())
          if (record is CustomRecord) record.customType,
      ];
      expect(customs, isEmpty);
