      await _livePresence!.store.unregister(_livePresence!.sessionId);
      _livePresence = null;
    }
    // Lease bookkeeping: release OUR lease (graceful exit, #428); a
    // viewer never touches the owner's lease.
    await _releaseSessionLease();
