          expect(
            settleRuns,
            isEmpty,
            reason: 'the settle must do bookkeeping only, never _startRun',
          );

          // I1: the file gained nothing after the seal.
          final after = await _recordsOnDisk(env);
          expect(
            after.length,
            before.length,
            reason: 'no session-JSONL append after the seal',
